PZA.enc = {}
local floor, abs, huge, tostring, concat = math.floor, math.abs, math.huge, tostring, table.concat
local fmt = string.format
local NONE = {}

-- One value: nil is null; a boolean true or false; a number as PZA.json renders it (NaN and +-Inf null, an integral
-- value under 1e15 through the 0-decimal format, any other through tostring); anything else through PZA.json.
local function v(x)
    local t = type(x)
    if t == "number" then
        if x ~= x or x == huge or x == -huge then return "null" end
        if x == floor(x) and abs(x) < 1e15 then return fmt("%.0f", x) end
        return tostring(x)
    end
    if x == nil then return "null" end
    if t == "boolean" then return x and "true" or "false" end
    return PZA.json(x)
end
PZA.enc.v = v

-- A Lua array (never a Java list) through one element encoder; nil is null.
local function list(a, f)
    if a == nil then return "null" end
    local n = #a
    if n == 0 then return "[]" end
    local out = {}
    for i = 1, n do out[i] = f(a[i]) end
    return "[" .. concat(out, ",") .. "]"
end

-- record wornLoc: One body location the worn clothing covers (PZA/1.6, me.worn).
--   loc: The body location's registry name, the WornItem's getLocation() (base:tshirt, base:jacket, base:pants); an item record's clothing.loc names the same slot.
--   bite: The summed getBiteDefense() of the Clothing worn there (0 at condition 0).
--   scratch: The summed getScratchDefense() of the Clothing worn there (0 at condition 0).
--   holes: PZA/1.6.1 (Task 9 fix 10): the summed getHolesNumber() of the Clothing worn there. The engine drops a garment from a body part wherever it has a hole there, and bite and scratch ignore holes, so an entry with holes above 0 defends less than its bite and scratch say (jar-reads-2 section 10); null in logs written before PZA/1.6.1.
--   cond: PZA/1.6.1 (Task 9 fix 10): the lowest getCondition() among the Clothing worn there (a garment at 0 defends nothing); null when unreadable and in logs written before PZA/1.6.1.
local function enc_wornLoc(t)
    if t == nil then return "null" end
    return "[" .. v(t.loc) .. "," .. v(t.bite) .. "," .. v(t.scratch) .. "," .. v(t.holes) .. "," .. v(t.cond) .. "]"
end
PZA.enc.wornLoc = enc_wornLoc

-- record room: The room ring (PZA/1.14, me.room, Plan 36 Task 1).
--   h: The clear tiles along each of the eight headings 0, 45, 90, 135, 180, 225, 270 and 315 degrees from the world's +x, in that order (atan2(y, x)'s convention, fwdAngle's in degrees: 90 is the world's +y), 0.0 to 3.0 in 0.5 steps: the farthest step from the player's position reached before the stop (a wall whose square the 1.5 step first enters reads 1.0); a point on the square already reached is clear, a point on a new square crosses the edge from the last square reached.
--   stop: What stopped each heading, in h's order (roomStop): wall, hop, door or open (3.0 reached clear).
--   tick: The client tick (the envelope's tick counter) the ring was read on: a ring is reused on the player's square for 3 client ticks, so it may predate its frame's tick.
local function enc_room(t)
    if t == nil then return "null" end
    return "[" .. list(t.h, v) .. "," .. list(t.stop, v) .. "," .. v(t.tick) .. "]"
end
PZA.enc.room = enc_room

-- record part: One body part below full health, bandaged or bleeding.
--   i: The body part index.
--   h: The body part's health.
--   bleeding: Whether the part bleeds, bleeding() (PZA/1.5, P24-G); a bandage clears the flag.
--   bleedingTime: The part's bleeding time, getBleedingTime(): kept under a bandage, which wears it ten times faster (jar-reads-2 T6b.5).
--   bandaged: Whether the part is bandaged, bandaged().
--   bandageLife: The bandage's life, getBandageLife(); null on an unbandaged part. A dirty rag's is 0 from the start.
--   bandageDirty: Whether the bandage is dirty, isBandageDirty() (its life at 0 or less: doubles the infection odds, T6b.6); null on an unbandaged part.
--   deep: Whether the part carries a deep wound, deepWounded(); a bandage clears the flag.
--   infected: Whether the wound is infected, isInfectedWound().
--   wound: Whether the part carries a wound a bandage treats: scratched(), isCut(), bitten() or deepWounded() reads true (PZAgent_Tend.lua's rank-1 test); false when all four read false, null when one is absent and none reads true (PZA/1.7.2, Plan 28 Task 1). A scratch that does not bleed reads true here and false in bleeding.
local function enc_part(t)
    if t == nil then return "null" end
    return "[" .. v(t.i) .. "," .. v(t.h) .. "," .. v(t.bleeding) .. "," .. v(t.bleedingTime) .. "," .. v(t.bandaged) .. "," .. v(t.bandageLife) .. "," .. v(t.bandageDirty) .. "," .. v(t.deep) .. "," .. v(t.infected) .. "," .. v(t.wound) .. "]"
end
PZA.enc.part = enc_part

-- record strain: The muscle strain of the two arms (PZA/1.7, body.strain).
--   l: The left arm's strain: the largest getStiffness() over Hand_L, ForeArm_L and UpperArm_L.
--   r: The right arm's strain: the largest getStiffness() over Hand_R, ForeArm_R and UpperArm_R.
local function enc_strain(t)
    if t == nil then return "null" end
    return "[" .. v(t.l) .. "," .. v(t.r) .. "]"
end
PZA.enc.strain = enc_strain

-- record zombie: One zombie in sense range.
--   id: The zombie's online id.
--   x: The world x in tiles.
--   y: The world y in tiles.
--   dist: The distance from the player in tiles.
--   hasTarget: Whether the zombie has a target.
--   crawler: Whether the zombie crawls.
--   health: The zombie's health.
--   onFloor: PZA/1.7 (Plan 24 Task 9 fix 11): true when the zombie lies on the floor, isOnFloor(): knocked down by a shove or a hit and not yet risen, or crawling. Null when it stands, and in logs written before PZA/1.7. A fallen zombie can be stomped (the stomp action) or finished by a weapon swing, which multiplies its damage by at least 5; a standing zombie within the held weapon's MinRange makes the stomp call shove that one instead (the stomp action refuses standing).
--   known: PZA/1.9 (Plan 30 Task 1): isTargetLocationKnown(), a target and seen just now (the target set and its bonus spot time running or its time since seen flesh under 1); on a client the packet carries the time since seen flesh beside a stale local spot time, so read it as targeted and seen (the jar read sneak-jar-read.md section 3; the owner alone runs the stealth test, #4660). Null when unread, and in logs written before PZA/1.9.
--   state: PZA/1.9 (Plan 30 Task 1): getRealState(), the zombie owner's state name the zombie packet carries (a string: idle, walktoward, turnalerted, pathfind, lunge, lunge-network, attack, attack-network, hitreaction, staggerback, getup, onground and others), empty when it answers no string (the jar read sneak-jar-read.md section 3). Null when unread, and in logs written before PZA/1.9.
--   behind: PZA/1.9 (Plan 30 Task 1): the player's isBehind(zombie), the melee press's own from-behind test: the zombie's forward direction dotted with the unit vector from the player to it above 0.6, about 53 degrees either side of straight behind (#4662: from behind against a zombie with no target a bat adds 5 to the crit chance, bare hands 30). Null when unread, and in logs written before PZA/1.9.
--   headX: PZA/1.10 (Plan 31 Task 2): a zombie lying on the floor (onFloor true): the world x of its head as estimated (PZAgent_Sense.lua's S.headOf): the floor attack tests its weapon's line against the fallen zombie's head bone first, the head x3 (#4679), but the bone's position is out of Lua's reach (its getters are on no exposed class), so the head is the zombie's position (its pelvis) plus 0.5 tiles along its body angle (getAnimAngleRadians) when it lies on its front (isFallOnFront) or crawls, else along the reverse: an inference to calibrate on the first live shot. Null when it stands or the angle is unread, and in logs written before PZA/1.10.
--   headY: PZA/1.10 (Plan 31 Task 2): the world y of a fallen zombie's head as headX estimates it. Null when it stands or the angle is unread, and in logs written before PZA/1.10.
local function enc_zombie(t)
    if t == nil then return "null" end
    return "[" .. v(t.id) .. "," .. v(t.x) .. "," .. v(t.y) .. "," .. v(t.dist) .. "," .. v(t.hasTarget) .. "," .. v(t.crawler) .. "," .. v(t.health) .. "," .. v(t.onFloor) .. "," .. v(t.known) .. "," .. v(t.state) .. "," .. v(t.behind) .. "," .. v(t.headX) .. "," .. v(t.headY) .. "]"
end
PZA.enc.zombie = enc_zombie

-- record portal: A door or a window.
--   open: Whether it is open.
--   locked: Whether it is locked (PZA/1.6, fail-closed): any of isLocked(), isLockedByKey() or a thumpable's isLockedByPadlock() for a door, isLocked() or isPermaLocked() for a window, reading true, and true when none of them can be read. True means may refuse, never will refuse: a locked door of a building refuses a player outside who holds no key (a door locked but not by key also refuses from one side), a player holding the key opens one locked by key, and a player inside unlocks it; a locked window struggles from outside and may lock for good, a perma-locked one never opens. Before PZA/1.6 isLocked() alone, false when unreadable.
--   barricaded: Whether it is barricaded.
local function enc_portal(t)
    if t == nil then return "null" end
    return "[" .. v(t.open) .. "," .. v(t.locked) .. "," .. v(t.barricaded) .. "]"
end
PZA.enc.portal = enc_portal

-- record windowPortal: A window (PZA/1.11, Plan 32 Task 6): the portal's fields, then its glass read off IsoWindow's getters (T101.1).
--   open: Whether it is open.
--   locked: Whether it is locked (PZA/1.6, fail-closed): any of isLocked(), isLockedByKey() or a thumpable's isLockedByPadlock() for a door, isLocked() or isPermaLocked() for a window, reading true, and true when none of them can be read. True means may refuse, never will refuse: a locked door of a building refuses a player outside who holds no key (a door locked but not by key also refuses from one side), a player holding the key opens one locked by key, and a player inside unlocks it; a locked window struggles from outside and may lock for good, a perma-locked one never opens. Before PZA/1.6 isLocked() alone, false when unreadable.
--   barricaded: Whether it is barricaded.
--   smashed: isSmashed(): the destroyed field, which canClimbThrough and the climb's cut test (#4366, T101.1); null when the getter cannot be read, and in logs written before PZA/1.11.
--   glass: Whether its broken glass is in: smashed and not isGlassRemoved() (T101.1), false on a window not smashed; a climb through it cuts a hand or a forearm 1 time in 2 (#4366, T101.2) unless the window action's clear removes it first (T101.3). Null when either getter cannot be read, and in logs written before PZA/1.11.
local function enc_windowPortal(t)
    if t == nil then return "null" end
    return "[" .. v(t.open) .. "," .. v(t.locked) .. "," .. v(t.barricaded) .. "," .. v(t.smashed) .. "," .. v(t.glass) .. "]"
end
PZA.enc.windowPortal = enc_windowPortal

-- record container: One container on a square.
--   type: The container type.
--   n: The number of items in it.
--   items: The full types of the items in it.
local function enc_container(t)
    if t == nil then return "null" end
    return "[" .. v(t.type) .. "," .. v(t.n) .. "," .. list(t.items, v) .. "]"
end
PZA.enc.container = enc_container

-- record water: A water source on a square (jar-reads-2 section 7, T6b.10): a sink or a toilet in a room gives clean Water, infinite until the water shut-off and then its reserve of 20; a river or a puddle gives TaintedWater.
--   amount: The water it holds, getFluidAmount(): 10000 for an infinite source.
--   tainted: Whether its water is tainted, isTaintedWater() (a fill takes TaintedWater, a poison until boiled).
--   infinite: Whether it never runs dry (piped before the shut-off, a river): getFluidCapacity() at 10000, which it answers when the private isWaterInfinite() holds (PZA/1.5.4; null in logs written before it, where isWaterInfinite was named missing).
local function enc_water(t)
    if t == nil then return "null" end
    return "[" .. v(t.amount) .. "," .. v(t.tainted) .. "," .. v(t.infinite) .. "]"
end
PZA.enc.water = enc_water

-- record square: One grid square.
--   x: The square's x.
--   y: The square's y.
--   z: The square's floor level.
--   solid: Whether the square blocks movement.
--   solidTrans: Whether the square blocks movement but not sight.
--   light: The square's light level.
--   room: The room name, null outside.
--   building: The building id, null outside.
--   door: The square's door, null when none.
--   window: The square's window, null when none (PZA/1.11: a windowPortal, the portal's fields then smashed and glass).
--   containers: The square's containers.
--   floor: The full types of the items on the floor.
--   blockN: Whether a step from this square to its north neighbour is blocked: a collide flag with no window, a closed or barricaded door, an intact closed or barricaded window, or a stair top (isBlockedTo).
--   blockW: Whether a step from this square to its west neighbour is blocked: a collide flag with no window, a closed or barricaded door, an intact closed or barricaded window, or a stair top (isBlockedTo).
--   edgeN: Whether a wall, door or window stands on the north edge, open or closed (isSomethingTo).
--   edgeW: Whether a wall, door or window stands on the west edge, open or closed (isSomethingTo).
--   hopN: Whether the square's own north edge is hoppable, has(IsoFlagType.HoppableN) (PZA/1.4, P24-C): a low fence the path follower climbs at a walk though isBlockedTo reads the edge blocked; false beside a solid wall on the same edge.
--   hopW: Whether the square's own west edge is hoppable, has(IsoFlagType.HoppableW) (PZA/1.4, P24-C): a low fence the path follower climbs at a walk though isBlockedTo reads the edge blocked; false beside a solid wall on the same edge.
--   water: The square's water source, null when none (PZA/1.5, P24-G): its first object whose hasWater() holds (a sink, a toilet, a bath, a well, a rain collector, a river, a puddle).
local function enc_square(t)
    if t == nil then return "null" end
    return "[" .. v(t.x) .. "," .. v(t.y) .. "," .. v(t.z) .. "," .. v(t.solid) .. "," .. v(t.solidTrans) .. "," .. v(t.light) .. "," .. v(t.room) .. "," .. v(t.building) .. "," .. enc_portal(t.door) .. "," .. enc_windowPortal(t.window) .. "," .. list(t.containers, enc_container) .. "," .. list(t.floor, v) .. "," .. v(t.blockN) .. "," .. v(t.blockW) .. "," .. v(t.edgeN) .. "," .. v(t.edgeW) .. "," .. v(t.hopN) .. "," .. v(t.hopW) .. "," .. enc_water(t.water) .. "]"
end
PZA.enc.square = enc_square

-- group me: The player's position and gait.
--   x: The world x in tiles.
--   y: The world y in tiles.
--   z: The floor level.
--   dir: The facing direction name.
--   pace: The measured pace in tiles a second.
--   moving: Whether the player is moving.
--   running: Whether the running flag is set.
--   sprinting: Whether the sprinting flag is set.
--   forceRun: The force-run flag read after the frame.
--   forceSprint: The force-sprint flag read after the frame.
--   autoWalk: Whether auto-walk is on.
--   zombiesSeen: The cell's zombie list size, the frame's one walk.
--   zombiesListed: The zombies the frame lists, those alive within the sense radius.
--   hour: The game's hour of day, 0 to 24, as a number.
--   attackers: The zombies attacking the player as the drag-down counts them (PZA/1.4, P24-C): getSurroundingAttackingZombies(), the standing zombies on the player's square and its eight neighbours that target the player within 0.9 tiles in an attack or lunge state; the drag-down kills at three (two at sandbox Strength 1).
--   hitReaction: The player's hit reaction, getHitReaction(), '' when none (PZA/1.4, P24-C): set by every zombie attack that reaches the damage roll, a defended one included; no swing starts while it is set.
--   dragDown: Whether the drag-down death is marked on the player, isDeathDragDown() (PZA/1.4, P24-C).
--   aiming: Whether the player is aiming, isAiming() (PZA/1.5, P24-G): the combat stance an aim holds, or a swing's own while its animation plays; a hit reaction clears it for the reaction's length, a run or a sprint for good.
--   forceAim: The force-aim flag read after the frame, isForceAim() (PZA/1.5.4, P24-T): re-asserted every frame while the stance is held (the game clears it every frame while its toggle-to-aim option is off), so true when the flag survived the frame (not cleared by a run key or a release), while aiming shows whether the update used it; null in logs written before PZA/1.5.4.
--   worn: PZA/1.6 (Plan 24 Task 9 fix 9, review-t18 ruling 5): the body locations the worn clothing covers, each with the bite and scratch defence of the Clothing items worn there summed (getWornItems(), a bag left out), in the order the game lists them; null on every frame whose list equals the last one carried, so a reader keeps the last list it saw (the first frame carries it, [] when nothing is worn), and in logs written before PZA/1.6. Read after an item or damage event, on the frame after the hit reaction rises, changes or ends or the attackers count rises from 0 (a zombie attack turned by the clothing makes a hole and no damage event, PZA/1.6.1), and every tenth frame otherwise. A zombie's scratch rolls under the scratch defence summed over the worn items covering the hit part, a bite under the bite defence (capped at 100): compare a garment's item record with the entry at its loc, an entry with holes above 0 counted as less than its bite and scratch.
--   loadedWidth: PZA/1.7 (Plan 24 Task 9 fix 11): the side in tiles of the square grid of chunks the client holds loaded around the player, getCell():getChunkMap(0):getWidthInTiles() (jar-reads-2 section 13): 104 at a 1280 x 720 window, 152 at 1920 x 1080. A square farther than half of it from the player's chunk on an axis may answer null to getGridSquare, so a walk to it fails no square before any path is asked; a leg of 8 x floor(loadedWidth / 16) - 8 tiles keeps the target inside with a chunk to spare. Carried on the first frame and on a frame where it changed, null otherwise (a reader keeps the last value it saw, as for worn), and in logs written before PZA/1.7.
--   sneaking: PZA/1.9 (Plan 30 Task 1): the player's sneaking flag, isSneaking(), one stored field that the sneak action writes once per change and nothing clears on an attack, a shove, a run, an aim or a hit (#4654); read off the player, never the want echoed. Under it the walk gait plays the crouched sneak walk and the run gait the sneak run (#4656). Null in logs written before PZA/1.9.
--   sneakLevel: PZA/1.9 (Plan 30 Task 1): the Sneak perk level, getPerkLevel(Perks.Sneak), 0 to 10: the level that sets the sneaking spot factor (#4657: 1.14 at 0 and 1.08 at 1, above upright beyond the close range, falling to 0.48 at 10). Null in logs written before PZA/1.9.
--   lookAngle: PZA/1.10 (Plan 31 Task 2): getLookAngleRadians(), the look in radians: the animation player's angle plus its twist plus the head look, the angle the melee hit list's dot (#4591) and the zombie bite's facing skip (#4688) read, the forward direction's angle while the animation player is not ready. The convention is Vector2.getDirection's atan2(y, x) on the world axes (the jar: Vector2.getDirection(FF) L105, AnimationPlayer.calculateAnimPlayerAngle L889), not dir's eight-point name of the written facing, which reads the new facing at once while the body turns toward it (#4689); calibrated on the first live frame before a grade relies on it. Not wrapped: the sum may pass pi. Null in logs written before PZA/1.10.
--   bodyAngle: PZA/1.10 (Plan 31 Task 2): getAnimAngleRadians(), the body's angle alone in radians (no twist, no head look), lookAngle's convention, the forward direction's angle while the animation player is not ready. Null in logs written before PZA/1.10.
--   fwdAngle: PZA/1.11 (Plan 32 Task 1): getDirectionAngleRadians(), the forward direction's angle in radians as the update left it (the facing the engine's three writers last wrote, the facing jar read's claim 15: the movement facing, the aim facing toward the mouse, a Lua face), lookAngle's convention; dir names it to 45 degrees only. Null in logs written before PZA/1.11.
--   twist: PZA/1.11 (Plan 32 Task 1): getTwist(), the upper body's twist off the body angle in degrees (the facing jar read's claim 15). Null in logs written before PZA/1.11.
--   aimAngle: PZA/1.11 (Plan 32 Task 1): the direction in radians of getAimVector(v), the vector the aimed update writes as the forward direction (the mouse's, the facing jar read's claim 7), lookAngle's convention; null when the vector reads zero length (no aim key counts, the force-aim included) and in logs written before PZA/1.11.
--   room: PZA/1.14 (Plan 36 Task 1): the room ring, the clear tiles around the player along eight headings (PZAgent_StanceWork.lua's one probe read, K.workRoom, which the footwork's heading turns also read), on the first frame and every third frame after it; null on the frames between (a reader keeps the last ring it saw, its tick naming the client tick it was read on), while the build carries no ring (no room cap in hello) and in logs written before PZA/1.14.
local function enc_me(t)
    if t == nil then return "null" end
    return "[" .. v(t.x) .. "," .. v(t.y) .. "," .. v(t.z) .. "," .. v(t.dir) .. "," .. v(t.pace) .. "," .. v(t.moving) .. "," .. v(t.running) .. "," .. v(t.sprinting) .. "," .. v(t.forceRun) .. "," .. v(t.forceSprint) .. "," .. v(t.autoWalk) .. "," .. v(t.zombiesSeen) .. "," .. v(t.zombiesListed) .. "," .. v(t.hour) .. "," .. v(t.attackers) .. "," .. v(t.hitReaction) .. "," .. v(t.dragDown) .. "," .. v(t.aiming) .. "," .. v(t.forceAim) .. "," .. list(t.worn, enc_wornLoc) .. "," .. v(t.loadedWidth) .. "," .. v(t.sneaking) .. "," .. v(t.sneakLevel) .. "," .. v(t.lookAngle) .. "," .. v(t.bodyAngle) .. "," .. v(t.fwdAngle) .. "," .. v(t.twist) .. "," .. v(t.aimAngle) .. "," .. enc_room(t.room) .. "]"
end
PZA.enc.me = enc_me

-- group stats: The player's character stats.
--   hunger: The hunger stat.
--   thirst: The thirst stat.
--   fatigue: The fatigue stat.
--   endurance: The endurance stat.
--   panic: The panic stat.
--   pain: The pain stat.
--   sickness: The food sickness stat.
--   wetness: The wetness stat.
--   temperature: The body temperature in degrees Celsius.
local function enc_stats(t)
    if t == nil then return "null" end
    return "[" .. v(t.hunger) .. "," .. v(t.thirst) .. "," .. v(t.fatigue) .. "," .. v(t.endurance) .. "," .. v(t.panic) .. "," .. v(t.pain) .. "," .. v(t.sickness) .. "," .. v(t.wetness) .. "," .. v(t.temperature) .. "]"
end
PZA.enc.stats = enc_stats

-- group body: The player's health and wounds.
--   health: The overall body health.
--   bleeding: The number of bleeding parts.
--   scratched: The number of scratched parts.
--   bitten: The number of bitten parts.
--   parts: The body parts below full health, and (PZA/1.5) any part bandaged or bleeding.
--   armPain: PZA/1.7 (Plan 24 Task 9 fix 11): the summed getPain() of the six arm parts Hand_L, Hand_R, ForeArm_L, ForeArm_R, UpperArm_L and UpperArm_R, rounded to 0.1, the sum the engine reads for a melee swing: once it passes 10 every swing's damage is divided by a tenth of it, so 20 halves the damage (jar-reads-2 section 11, rows 4368-4371). A part's pain includes its muscle strain (stiffness / 3.5) and its wounds' pain, so a bite on an arm holds it up and a rest does not lower that; null in logs written before PZA/1.7.
--   strain: PZA/1.7 (Plan 24 Task 9 fix 11): the muscle strain of each arm, the largest getStiffness() over the three arm parts of its side (hand, forearm, upper arm), rounded to 0.1. A melee swing adds to the weapon's arm (both arms for a two-hander), a miss as much as a hit, a shove adds to both arms and a stomp to the right leg alone; it decays on the server by about 5.76 a real minute (jar-reads-2 section 11). Null in logs written before PZA/1.7.
local function enc_body(t)
    if t == nil then return "null" end
    return "[" .. v(t.health) .. "," .. v(t.bleeding) .. "," .. v(t.scratched) .. "," .. v(t.bitten) .. "," .. list(t.parts, enc_part) .. "," .. v(t.armPain) .. "," .. enc_strain(t.strain) .. "]"
end
PZA.enc.body = enc_body

-- group load: The player's carried weight and its moodle level.
--   weight: The carried weight.
--   max: The maximum carry weight.
--   level: The heavy-load moodle level.
--   n: The number of inventory items.
local function enc_load(t)
    if t == nil then return "null" end
    return "[" .. v(t.weight) .. "," .. v(t.max) .. "," .. v(t.level) .. "," .. v(t.n) .. "]"
end
PZA.enc.load = enc_load

-- group weapon: The primary hand weapon.
--   type: The weapon's full type.
--   cond: The weapon's condition.
--   reach: The engine's reach, max range times range mod.
--   ammo: The loaded ammunition count, null for a melee weapon.
local function enc_weapon(t)
    if t == nil then return "null" end
    return "[" .. v(t.type) .. "," .. v(t.cond) .. "," .. v(t.reach) .. "," .. v(t.ammo) .. "]"
end
PZA.enc.weapon = enc_weapon

-- group action: The current timed action.
--   class: The head action's Type.
--   n: The number of queued actions.
local function enc_action(t)
    if t == nil then return "null" end
    return "[" .. v(t.class) .. "," .. v(t.n) .. "]"
end
PZA.enc.action = enc_action

-- group act: The current skill.
--   aid: The skill's action id.
--   state: The skill's state.
--   step: PZA/1.8 (Plan 28 Task 7a): the melee reflex's step in force when the frame was read (face, swing, shove, stomp, floor, stomp_walk, knock_wait, back, close, stand or hit, and since PZA/1.13 work, cornered and pile, as its progress lines name them: the step of the client tick that ran before the frame's read); null for every other skill, and in logs written before PZA/1.8.
local function enc_act(t)
    if t == nil then return "null" end
    return "[" .. v(t.aid) .. "," .. v(t.state) .. "," .. v(t.step) .. "]"
end
PZA.enc.act = enc_act

-- group cost: The mod's own cost on the client.
--   tickMs: The previous tick's whole body in ms (a single tick on the 1 ms clock).
--   actMs: This tick's skill tick in ms (a single tick).
--   senseMs: This tick's events and frame read in ms (a single tick).
--   mapMs: This tick's scan or watch step in ms (a single tick).
--   linkMs: The previous tick's flush in ms.
--   tickMaxMs: The worst body since the last frame, in ms.
--   over5: The bodies of 5 ms or more since the last frame.
--   dropped: The number of lines dropped.
--   pollMs: This tick's command poll in ms, the ack write included (a single tick).
--   startMs: This tick's command start in ms, Main's scan or rate answer or the runner's start (a single tick).
--   maxActMs: The worst skill tick since the last frame, in ms.
--   maxSenseMs: The worst events and frame read since the last frame, in ms.
--   maxMapMs: The worst scan or watch step since the last frame, in ms.
--   maxLinkMs: The worst flush since the last frame, in ms.
--   maxPollMs: The worst command poll since the last frame, in ms.
--   maxStartMs: The worst command start since the last frame, in ms.
--   roomMs: PZA/1.14 (Plan 36 Task 1): this frame's me.room read in ms (a single read on the 1 ms clock; 0 for a ring reused within its 3 client ticks on the player's square and on a frame carrying no ring, so a reader of the ring's cost takes the frames whose me.room is set); null in logs written before PZA/1.14.
local function enc_cost(t)
    if t == nil then return "null" end
    return "[" .. v(t.tickMs) .. "," .. v(t.actMs) .. "," .. v(t.senseMs) .. "," .. v(t.mapMs) .. "," .. v(t.linkMs) .. "," .. v(t.tickMaxMs) .. "," .. v(t.over5) .. "," .. v(t.dropped) .. "," .. v(t.pollMs) .. "," .. v(t.startMs) .. "," .. v(t.maxActMs) .. "," .. v(t.maxSenseMs) .. "," .. v(t.maxMapMs) .. "," .. v(t.maxLinkMs) .. "," .. v(t.maxPollMs) .. "," .. v(t.maxStartMs) .. "," .. v(t.roomMs) .. "]"
end
PZA.enc.cost = enc_cost

-- the frame line: One observation of the player, sent every frame, a delta eliding unchanged groups as true.
--   kind: The line kind.
--   seq: The line's sequence number.
--   tick: The client tick the line was written on.
--   wallMs: The client's wall clock in milliseconds.
--   gameMin: The game clock in minutes.
--   worldAge: The world age in hours.
--   me: The player's position and gait.
--   stats: The player's character stats.
--   body: The player's health and wounds.
--   load: The player's carried weight and its moodle level.
--   weapon: The primary hand weapon, null when none.
--   action: The current timed action, null when none.
--   act: The current skill, null when none.
--   zombies: The zombies in sense range, nearest first.
--   cost: The mod's own cost on the client.
PZA.enc.frame = function(b, same)
    same = same or NONE
    return "[\"frame\""
        .. "," .. v(b.seq)
        .. "," .. v(b.tick)
        .. "," .. v(b.wallMs)
        .. "," .. v(b.gameMin)
        .. "," .. v(b.worldAge)
        .. "," .. (same.me == true and "true" or enc_me(b.me))
        .. "," .. (same.stats == true and "true" or enc_stats(b.stats))
        .. "," .. (same.body == true and "true" or enc_body(b.body))
        .. "," .. (same.load == true and "true" or enc_load(b.load))
        .. "," .. (same.weapon == true and "true" or enc_weapon(b.weapon))
        .. "," .. (same.action == true and "true" or enc_action(b.action))
        .. "," .. (same.act == true and "true" or enc_act(b.act))
        .. "," .. list(b.zombies, enc_zombie)
        .. "," .. (same.cost == true and "true" or enc_cost(b.cost))
        .. "]"
end

-- the map line: One part of a map scan: the squares it carries by position.
--   kind: The line kind.
--   seq: The line's sequence number.
--   tick: The client tick the line was written on.
--   wallMs: The client's wall clock in milliseconds.
--   mode: A full scan or a delta of changed squares.
--   scanId: The scan this part belongs to.
--   part: This part's number, from 1.
--   parts: The scan's number of parts.
--   squares: The squares this part carries.
--   missing: The Java member names the scan could not read on this part.
PZA.enc.map = function(b)
    return "[\"map\""
        .. "," .. v(b.seq)
        .. "," .. v(b.tick)
        .. "," .. v(b.wallMs)
        .. "," .. v(b.mode)
        .. "," .. v(b.scanId)
        .. "," .. v(b.part)
        .. "," .. v(b.parts)
        .. "," .. list(b.squares, enc_square)
        .. "," .. list(b.missing, v)
        .. "]"
end
